31	      --color-pink-rgb: 255, 107, 157;
32	      --color-teal: #4ecdc4;
33	      --color-teal-rgb: 78, 205, 196;
34	      --color-mint: #95e1d3;
35	      --color-mint-rgb: 149, 225, 211;
36	      --color-purple: #d946ef;
37	      --color-purple-rgb: 217, 70, 239;
38	      --color-orange: #ff9500;
39	      --color-orange-rgb: 255, 149, 0;
40	    }
41	
42	    * {
43	      margin: 0;
44	      padding: 0;
45	      box-sizing: border-box;
46	    }
47	    html, body {
48	      height: 100%;
49	    }
50	    body {
51	      display: flex;
52	      flex-direction: column;
53	      justify-content: center;
54	      align-items: center;
55	      gap: 20px;
56	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
57	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
58	      color: var(--color-white);
59	      font-size: 14px;
60	      padding: 20px;
61	      margin: 0;
62	    }
63	    .circle-container {
64	      cursor: pointer;
65	      border: none;
66	      background: none;
67	      padding: 0;
68	      position: relative;
69	      transition: transform var(--transition-normal);
70	      user-select: none;
71	      touch-action: manipulation;
72	      -webkit-tap-highlight-color: transparent;
73	    }
74	    .circle-container:focus {
75	      outline: none;
76	    }
77	    .circle-container:hover {
78	      transform: scale(1.05) translateZ(0);
79	    }
80	    .circle-container:focus-visible {
81	      transform: scale(1.08) translateZ(0);
82	      outline: 3px solid rgba(255, 255, 255, 0.8);
83	      outline-offset: 10px;
84	      border-radius: 50%;
85	      animation: focusPulse 0.4s ease-out;
86	    }
87	    svg {
88	      width: min(400px, 80vw);
89	      height: min(400px, 80vw);
90	      display: block;
91	      animation: fadeIn var(--transition-slow), hintBounce 2.5s ease-in-out 1s 1 backwards;
92	      will-change: filter, transform;
93	    }
94	    circle {
95	      fill: var(--color-white);
96	      stroke: rgba(255, 255, 255, 0.25);
97	      stroke-width: 1.5;
98	      animation: pulse var(--pulse-duration) ease-in-out infinite;
99	      filter: drop-shadow(0 20px 40px var(--shadow-color));
100	      transition: fill 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), r 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.35s ease, filter 0.35s ease, opacity 0.35s ease;
101	      will-change: fill, r, filter;
102	      contain: paint;
103	    }
104	    .circle-container:is(:hover, :focus-visible) circle {
105	      fill: #e8f4f8;
106	      r: 205;
107	      stroke: rgba(255, 255, 255, 0.5);
108	      filter: drop-shadow(0 20px 50px rgba(255, 255, 255, 0.2));
109	    }
110	    .circle-container.active:not([class*="color-mode-"]) circle {
111	      fill: var(--color-gold);
112	      stroke: rgba(255, 215, 0, 0.4);
113	      animation: pulse-active 0.6s ease-in-out;
114	      filter: drop-shadow(0 20px 50px rgba(255, 215, 0, 0.6));
115	      r: 200;
116	    }
117	
118	    .circle-container.color-mode-1 { --mode-color: var(--color-pink); --mode-rgb: var(--color-pink-rgb); }
119	    .circle-container.color-mode-2 { --mode-color: var(--color-teal); --mode-rgb: var(--color-teal-rgb); }
120	    .circle-container.color-mode-3 { --mode-color: var(--color-mint); --mode-rgb: var(--color-mint-rgb); }
121	    .circle-container.color-mode-4 { --mode-color: var(--color-purple); --mode-rgb: var(--color-purple-rgb); }
122	    .circle-container.color-mode-5 { --mode-color: var(--color-orange); --mode-rgb: var(--color-orange-rgb); }
123	
124	    [class*="color-mode-"] circle {
