559	<body>
560	  <button type="button" class="help-btn" id="help-btn" aria-label="Show keyboard shortcuts" title="Help (press ?)">?</button>
561	
562	  <div class="modal" id="help-modal" role="dialog" aria-labelledby="modal-header" aria-modal="true">
563	    <div class="modal-content">
564	      <button type="button" class="modal-close" id="modal-close" aria-label="Close help">✕</button>
565	      <div class="modal-header" id="modal-header">Keyboard Shortcuts</div>
566	      <div class="modal-shortcuts">
567	        <div class="shortcut-item">
568	          <span class="shortcut-key">C</span>
569	          <span class="shortcut-desc">Cycle to next color</span>
570	        </div>
571	        <div class="shortcut-item">
572	          <span class="shortcut-key">X</span>
573	          <span class="shortcut-desc">Random color</span>
574	        </div>
575	        <div class="shortcut-item">
576	          <span class="shortcut-key">R</span>
577	          <span class="shortcut-desc">Reset to default</span>
578	        </div>
579	        <div class="shortcut-item">
580	          <span class="shortcut-key">Space</span>
581	          <span class="shortcut-desc">Toggle active state</span>
582	        </div>
583	        <div class="shortcut-item">
584	          <span class="shortcut-key">↩</span>
585	          <span class="shortcut-desc">Toggle active state</span>
586	        </div>
587	        <div class="shortcut-item">
588	          <span class="shortcut-key">Esc</span>
589	          <span class="shortcut-desc">Reset to default</span>
590	        </div>
