621	        { class: 'color-mode-3', name: 'Mint' },
622	        { class: 'color-mode-4', name: 'Purple' },
623	        { class: 'color-mode-5', name: 'Orange' }
624	      ];
625	
626	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
627	
628	      const CONFIG = {
629	        storageKey: 'circle-state',
630	        tapDelay: 300,
631	        colorShiftDuration: 500,
632	        saveDebounceDuration: 100,
633	        keyDebounce: 50,
634	        isTouch: (() => {
635	          const hasCoarsePointer = window.matchMedia?.('(pointer:coarse)').matches ?? false;
636	          const hasTouchEvents = 'ontouchstart' in window;
637	          const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
