645	        modeIndicator: document.getElementById('mode-indicator'),
646	        cycleBtn: document.getElementById('cycle-btn'),
647	        randomBtn: document.getElementById('random-btn'),
648	        resetBtn: document.getElementById('reset-btn'),
649	        helpBtn: document.getElementById('help-btn'),
650	        helpModal: document.getElementById('help-modal'),
651	        modalClose: document.getElementById('modal-close')
652	      };
653	
654	      let state = { active: false, colorMode: 0 };
655	      let tapCount = 0;
656	      let tapTimeout = null;
657	      let animatingColorShift = false;
658	      let saveTimeout = null;
659	      let lastKeyTime = 0;
660	
661	      const haptic = (duration) => {
