667	        }
668	      };
669	
670	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
671	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
672	
673	      const storage = {
674	        save() {
675	          clearTimeout(saveTimeout);
676	          saveTimeout = setTimeout(() => {
677	            try {
678	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
679	            } catch (e) {
