781	        animatingColorShift = true;
782	        state.colorMode = getRandomColorMode();
783	        state.active = true;
784	        haptic([20, 10, 20]);
785	        el.circle.classList.add('color-shifting');
786	        const timeoutId = setTimeout(() => {
787	          el.circle?.classList.remove('color-shifting');
788	          animatingColorShift = false;
789	        }, CONFIG.colorShiftDuration);
790	        applyState();
791	        storage.save();
792	        return timeoutId;
793	      };
794	
795	      const resetState = () => {
